import{TASKS05,EXERCISES05,packBstar05,assess05,checkExercise05,GOLDEN_TREE05,LIFT_TREE05,ENUM05,describeError02}from'./bstar05.mjs';import{metricsReport}from'./metrics03.mjs';import{board}from'../lessons/02/teaching/visuals.mjs';
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const swapNames=(treeText,a,b)=>treeText.replace(new RegExp(`(?<![A-Za-z])${a}(?![A-Za-z])`,'g'),'\u0000').replace(new RegExp(`(?<![A-Za-z])${b}(?![A-Za-z])`,'g'),a).replace(/\u0000/g,b);
export function lab05Page({code,task,quizBlock=''}){return`<main id="main" class="wrap focused-lesson"><header class="focused-hero"><div class="breadcrumbs"><a href="../../index.html">课程</a> / Lab 05</div><h1>树给横坐标，轮廓线给高度</h1><p class="lead">按先序遍历重建布局，维护整段轮廓线，解释每个落点为什么在那里。</p><nav class="focused-nav" aria-label="本课学习路径"><a href="#video">01 互动教学</a><a href="#lab">02 综合 Lab · Python</a><a href="#quiz">03 课后习题</a></nav></header>
<section id="video" class="focused-section"><span id="film"></span><span class="eyebrow">01 / LEARN</span><h2>互动讲解</h2><p class="small">先看一遍；树与布图同时高亮，轮廓线逐步更新。</p><iframe id="interactive-teaching-frame" title="Lab5互动教学" src="teaching/?embed=1&v=bstar-1" allow="autoplay; fullscreen" scrolling="no" style="width:100%;height:850px;border:0;display:block"></iframe></section>
<section id="lab" class="focused-section"><span class="eyebrow">02 / PLACE · REPAIR · EDIT</span><h2>打包实验台</h2><p>三项任务：手算托高落点、纠正“只看父块顶边”的错误更新、移动节点并解释谁要重摆。</p><label>选择任务 <select id="lab05-task">${TASKS05.map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('')}</select></label><p id="lab05-prompt"></p><button id="lab05-reset">重置当前任务</button>
<div class="lab04-console"><label>B*-树（写法 A(B(C(E,-),-),D)） <input id="lab05-tree" class="wide-input" spellcheck="false"></label><button id="lab05-decode" class="primary">解码并摆放</button><button id="lab05-swap">交换两个名称</button><label>名称1 <select id="lab05-swap-a">${'ABCDE'.split('').map(c=>`<option>${c}</option>`).join('')}</select></label><label>名称2 <select id="lab05-swap-b">${'ABCDE'.split('').map(c=>`<option${c==='D'?' selected':''}>${c}</option>`).join('')}</select></label><p id="lab05-parse" role="status"></p></div>
<div id="lab05-board" class="lab02-board"></div><div class="lab04-side"><div id="lab05-contour"></div><div id="lab05-order"></div></div><div id="lab05-metrics"></div><button id="lab05-enum">穷举这五棵树的合法摆法（一次性，约1秒）</button><p id="lab05-enum-result" role="status"></p>
<div id="lab05-evidence"></div><label>写下你的推理（托高来自哪段、谁需要重摆）<textarea id="lab05-explanation" rows="3" style="display:block;width:100%"></textarea></label><button id="lab05-check" class="primary">检查并保存</button> <button id="lab05-hint">需要一点提示</button><p id="lab05-result" role="status" style="white-space:pre-line"></p>
<article id="python" class="python-integrated"><h3>Python Lab：实现完整打包器 pack_bstar</h3><p>${esc(task.prompt.zh)}</p><details><summary>接口合同与错误码</summary><p>tree 是 (id, left, right) 嵌套元组，叶子可写 (id,None,None) 或直接写 id 字符串；modules 形如 {'A':(宽,高)}。先序遍历：左孩子 x=父x+父宽，右孩子 x=父x；y=整个覆盖区间 [x,x+w) 下的最高轮廓。放块后拆分旧区间、保留两侧残段、合并相邻等高段。返回 {'ok','errors','order','coords','rows','contour','trace'}；rows 按 id 排序且须通过已提供的 validate_layout。错误码：unknown:X、duplicate:X、missing:清单。</p><p>${task.tests.length}项检查是基线。再写一个自己的测试：它能排除哪种错误实现（例如“只看父块顶边”或“删掉整段残段”）？</p></details><textarea id="python-source" class="python-editor" aria-label="Python source code" spellcheck="false">${esc(code)}</textarea><div class="python-toolbar"><button id="python-run" class="primary">运行综合检查</button><button id="python-stop" disabled>停止</button><button id="python-reset">恢复模板</button></div><pre id="python-output" class="python-output" role="status">尚未检查。修改代码后，需要重新运行。</pre></article></section>
<section id="quiz" class="focused-section"><span class="eyebrow">03 / TRANSFER · COUNTEREXAMPLE · BOUNDARY</span><h2>课后练习：把落点说清楚</h2><p>除了数值，也写出推理。做完后可以对照参考要点检查。</p>${EXERCISES05.map(q=>`<article class="extended-exercise" data-exercise05="${q.id}"><h3>${esc(q.title)}</h3><p>${esc(q.prompt)}</p><div class="exercise-fields">${q.fields.map(([key,label])=>`<label>${esc(label)} <input type="number" step="any" data-field="${key}"></label>`).join('')}</div><label>你的推理<textarea data-explain rows="3"></textarea></label><button data-check>检查并保存</button> <button data-reveal>查看参考要点</button><p data-result role="status"></p><p data-rubric hidden>${esc(q.rubric)}</p></article>`).join('')}${quizBlock}</section></main>`;}
export function bindLab05({progress,save}){const $=s=>document.querySelector(s);let task=TASKS05[0],result=null,edited=false,hint=false;
 progress.lab05Submissions=progress.lab05Submissions||{};progress.exercises05=progress.exercises05||{};
 function render(){$('#lab05-prompt').textContent=task.prompt;$('#lab05-tree').value=task.tree;
  $('#lab05-parse').textContent=result?(result.ok?`解码成功：先序 ${result.order.join(' → ')}；最终轮廓 ${result.contour.map(c=>`[${c.x1},${c.x2})=${c.h}`).join('  ')}`:'解码失败：'+result.errors.join('；')):'点击"解码并摆放"开始。';
  const rows=result&&result.ok?result.rows:packBstar05(task.startTree||GOLDEN_TREE05).rows;
  $('#lab05-board').innerHTML=`<svg viewBox="0 0 960 540" role="group" aria-label="B*-tree打包结果"><defs><pattern id="collision" width="8" height="8" patternUnits="userSpaceOnUse" patternTransform="rotate(45)"><rect width="8" height="8" fill="#efc2ad"/><path d="M0 0V8" stroke="#a74330" stroke-width="3"/></pattern></defs>${board(rows,task.outline,{x:70,y:60,w:810,h:415})}</svg>`;
  $('#lab05-contour').innerHTML=result&&result.ok?`<h3>最终轮廓线</h3><table style="width:100%"><tbody>${result.contour.map(c=>`<tr><td>[${c.x1}, ${c.x2})</td><td>高 ${c.h}</td></tr>`).join('')}</tbody></table>`:'<h3>轮廓线</h3><p>解码后显示。</p>';
  $('#lab05-order').innerHTML=result&&result.ok?`<h3>先序与坐标</h3><table style="width:100%"><tbody>${result.order.map(id=>{const c=result.coords[id];return`<tr><td>${esc(id)}</td><td>(${c.x}, ${c.y}) ${c.w}×${c.h}</td></tr>`;}).join('')}</tbody></table>`:'<h3>先序</h3><p>解码后显示。</p>';
  const r=result&&result.ok?result.report:null;
  $('#lab05-metrics').innerHTML=r?`<div class="metric-line"><span>合法性</span><b>${r.legal?'通过 Lab2 检查':'未通过：'+r.errors.map(describeError02).join('，')}</b></div><div class="metric-line"><span>包围盒</span><b>${r.bbox.width}×${r.bbox.height}=${r.bbox.area}</b></div><div class="metric-line"><span>盒内空余</span><b>${r.bbox_dead}</b></div>`:'<p class="metric-line">解码失败时没有可评价的布局。</p>';
  $('#lab05-evidence').innerHTML=`<div class="exercise-fields">${task.fields.map(([key,label])=>`<label>${esc(label)} <input id="lab05-${key}" type="number" step="any"${key==='moved'?' max="1"':''}></label>`).join('')}</div>`;}
 $('#lab05-task').onchange=e=>load(e.target.value);$('#lab05-reset').onclick=()=>load(task.id);
 $('#lab05-decode').onclick=()=>{task={...task,tree:$('#lab05-tree').value};result=packBstar05($('#lab05-tree').value);edited=true;render();};
 $('#lab05-swap').onclick=()=>{const a=$('#lab05-swap-a').value,b=$('#lab05-swap-b').value;if(a===b){$('#lab05-parse').textContent='请选择两个不同的名称。';return;}const next=swapNames($('#lab05-tree').value,a,b);$('#lab05-tree').value=next;task={...task,tree:next};result=packBstar05(next);edited=true;render();};
 $('#lab05-hint').onclick=()=>{hint=true;progress.lab05Submissions[task.id]={...(progress.lab05Submissions[task.id]||{}),hintUsed:true};save();$('#lab05-result').textContent=task.hint;};
 $('#lab05-check').onclick=()=>{const e={};for(const key of task.fields.map(f=>f[0]))e[key]=$('#lab05-'+key)?.value;const attempt=$('#lab05-tree').value.replace(/\s+/g,'')!==task.startTree.replace(/\s+/g,'');const res=assess05(task.id,$('#lab05-tree').value,e,attempt);if(!attempt)res.errors.unshift('先修改树或完成计算，再提交。加载示例不算独立完成。');
  const explanation=$('#lab05-explanation').value;
  progress.lab05Submissions[task.id]={version:1,tree:$('#lab05-tree').value,evidence:e,numericPassed:res.ok,explanation,hintUsed:hint,explanationStatus:'submitted-not-graded'};save();
  $('#lab05-result').textContent=res.errors.length?res.errors.join('\n'):explanation.trim().length<30?'条件和数值通过，请再写清楚托高来自哪一段、谁需要重摆。':'条件和数值通过，解释已保存。请确认你的落点解释用到了整段轮廓。';};
 $('#lab05-enum').onclick=()=>{if($('#lab05-enum-result').textContent)return;const t0=performance.now();let fit=0,min=Infinity;
  const shapes=[];function gen(n){if(n===0)return[null];if(n===1)return['L'];const out=[];for(let l=0;l<=n-1;l++)for(const L of gen(l))for(const R2 of gen(n-1-l))out.push([L,R2]);return out;}
  const perms=(a)=>{if(a.length<=1)return[a];const o=[];for(let i=0;i<a.length;i++){const rest=[...a.slice(0,i),...a.slice(i+1)];for(const p of perms(rest))o.push([a[i],...p]);}return o;};
  for(const shape of gen(5))for(const perm of perms(['A','B','C','D','E'])){let idx=0;const build=n=>{if(n===null)return null;const id=perm[idx++];return n==='L'?{id}:{id,left:build(n[0]),right:build(n[1])};};
   try{const r=packBstar05(build(shape));if(r.check.legal){fit++;if(r.report.bbox.area<min)min=r.report.bbox.area;}}catch(err){}}
  $('#lab05-enum-result').textContent=`穷举完成（${Math.round(performance.now()-t0)}ms）：5040 棵中 ${fit} 棵合法装进 10×8，最小包围盒面积 ${min}。这只属于当前五块与外框。`;};
 function load(id){task=TASKS05.find(t=>t.id===id);result=null;edited=false;hint=!!progress.lab05Submissions[task.id]?.hintUsed;$('#lab05-result').textContent='';$('#lab05-explanation').value='';render();}
 for(const article of document.querySelectorAll('[data-exercise05]')){const id=article.dataset.exercise05,saved=progress.exercises05[id]||{};for(const input of article.querySelectorAll('[data-field]'))input.value=saved.values?.[input.dataset.field]??'';article.querySelector('[data-explain]').value=saved.explanation||'';let revealed=!!saved.revealed;
  article.querySelector('[data-check]').onclick=()=>{const values=Object.fromEntries([...article.querySelectorAll('[data-field]')].map(e=>[e.dataset.field,e.value])),explanation=article.querySelector('[data-explain]').value,ok=checkExercise05(id,values);progress.exercises05[id]={values,explanation,numericPassed:ok,revealed,explanationStatus:'submitted-not-graded'};save();article.querySelector('[data-result]').textContent=!ok?'数值还不对，请核对落点、残段或穷举数字。':explanation.trim().length<30?'数值通过，请补上你的推理。':'数值通过，解释已保存。请按参考要点检查依据。'+(revealed?'（已查看参考）':'');};
  article.querySelector('[data-reveal]').onclick=()=>{revealed=true;article.querySelector('[data-rubric]').hidden=false;progress.exercises05[id]={...(progress.exercises05[id]||{}),revealed:true};save();article.querySelector('[data-result]').textContent='参考要点已显示，不计作独立完成的证明。';};}
 load(TASKS05[0].id);
}
